(function(){
  'use strict';
  const D=window.WBData,M=window.WBModel,KEY='personal-workbench.preview.v1';
  const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(n,cls='')=>`<img class="icon ${cls}" src="assets/${n}.svg" alt="">`;
  let state=M.empty(),storageOK=true,route='home',platform='共用内容库',radarFilter='全部',reviewPeriod='daily',toastTimer;
  try{state=M.restore(localStorage.getItem(KEY));}catch{storageOK=false;}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-state').textContent='已保存在当前浏览器';}catch{storageOK=false;$('#storage-warning').hidden=false;$('#save-state').textContent='本次改动暂未保存';}}
  function toast(t){$('#toast').textContent=!storageOK&&/保存|添加|加入/.test(t)?'本次改动仅在页面中生效，浏览器暂时无法保存。':t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
  const link=(to,text,cls='text-button')=>`<a class="${cls}" href="#${to}">${text}${icon('arrow-right')}</a>`;
  const badge=(text,tone='neutral')=>`<span class="badge ${tone}">${esc(text)}</span>`;
  const heading=(title,sub='',action='')=>`<div class="section-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
  function allTasks(){return [...D.tasks,...state.tasks,...state.trials.map(id=>{const t=D.tools.find(x=>x.id===id);return t?{id:'trial-'+id,title:'试一试 '+t.name,minutes:t.minutes,tag:'工具试用',body:t.trial,evidence:t.criteria}:null;}).filter(Boolean)];}
  function tasksHTML(){return allTasks().map(t=>`<div class="task-row ${state.done[t.id]?'completed':''}"><input class="task-check" type="checkbox" id="done-${t.id}" data-task="${t.id}" aria-label="完成任务：${esc(t.title)}" ${state.done[t.id]?'checked':''}><button class="task-content" data-action="task" data-id="${t.id}"><strong>${esc(t.title)}</strong><span>${esc(t.tag)}<span class="task-time">${icon('clock-3')}${t.minutes} 分钟</span></span></button>${icon('chevron-right','task-chevron')}</div>`).join('');}
  function projectHTML(p,compact=false){return `<button class="project-row ${compact?'compact':''}" data-action="project" data-id="${p.id}"><span class="project-icon ${p.id}">${icon(p.icon)}</span><span class="project-info"><span class="project-name">${p.title}</span><span class="project-next">${esc(p.next)}</span>${p.steps?`<span class="stage-track" aria-label="当前阶段：${p.stage}">${p.steps.map((s,i)=>`<span class="${i<p.current?'past':i===p.current?'current':''}" title="${s}"></span>`).join('')}</span>`:''}</span><span class="project-status">${badge(p.stage,p.id==='packrivo'?'amber':'blue')}${icon('chevron-right')}</span></button>`;}
  function toolHTML(t,full=false){return `<article class="tool-card ${full?'full':''}"><div class="tool-top"><span class="tool-mark ${t.tone}">${t.monogram}</span><div><strong>${t.name}</strong><span>${t.type}</span></div>${badge(t.label,t.tone==='amber'?'amber':'blue')}</div><button class="tool-title" data-action="tool" data-id="${t.id}">${t.title}${icon('arrow-up-right')}</button><p>${esc(full?t.summary:t.benefit)}</p><div class="tool-bottom"><span>${icon('clock-3')}${t.minutes} 分钟尝试</span><button class="small-button" data-action="tool" data-id="${t.id}">了解与试用</button></div></article>`;}
  function noteHTML(){return `<section class="notes-block"><div class="note-label">${icon('notebook-pen')}<div><h2>这个板块，我想补充…</h2><p>记录你的想法、使用感受或想调整的地方。</p></div></div><form id="note-form"><label class="sr-only" for="section-note">板块备注</label><textarea id="section-note" name="note" rows="2" maxlength="5000" placeholder="例如：这里我还想看到什么？">${esc(state.notes[route]||'')}</textarea><div class="note-actions"><span>输入自动保存在当前浏览器</span><button class="small-button" type="submit">保存备注</button></div></form></section>`;}
  function pageHeader(){const s=D.sections.find(x=>x.id===route);return `<div class="page-heading"><div><div class="page-kicker">${icon(s.icon)}${route==='home'?'我的一天':s.name}</div><h1>${route==='home'?'今天，把重要的事向前推一步。':s.name}</h1><p>${s.desc}</p></div><button class="outline-button help-toggle" data-action="section-help" aria-expanded="false">${icon('circle-help')}板块说明</button></div><div id="section-explainer" class="explainer" hidden>${icon('info')}<p>${s.help}</p></div>`;}
  function home(){const ts=allTasks(),done=ts.filter(t=>state.done[t.id]).length,total=ts.reduce((a,t)=>a+t.minutes,0);return `<div class="today-strip"><div>${icon('calendar-days')}<strong>${new Intl.DateTimeFormat('zh-CN',{timeZone:'America/Los_Angeles',month:'long',day:'numeric',weekday:'long'}).format(new Date())}</strong><span class="strip-divider"></span><span>每天约 1 小时，目标两天一条内容</span></div><span class="preview-tag">任务为建议试排，可点击体验</span></div><div class="home-grid"><div class="home-primary"><section class="panel tasks-panel">${heading('今天要做的事',`已完成 ${done} / ${ts.length} 项 · 当前试排 ${total} 分钟`,`<button class="icon-button soft" data-action="new-task" aria-label="添加今日任务">${icon('plus')}</button>`)}<div class="tasks">${tasksHTML()}</div><div class="section-foot">${icon('info')}先完成眼前这一步。任务可勾选，也可点开查看完成标准。</div></section><section class="panel projects-panel">${heading('项目进度','用阶段看进展，每个项目都有下一步。',link('projects','全部项目'))}<div class="project-list">${D.projects.map(p=>projectHTML(p,true)).join('')}</div></section></div><section class="recommendations">${heading('值得你关注', '新工具、新变化，先看对你有什么用。',link('radar','全部'))}<div class="recommendation-list">${D.tools.slice(0,2).map(t=>toolHTML(t)).join('')}</div><a class="radar-more" href="#radar">${icon('globe')}<span><strong>外贸与独立站，也在关注中</strong><small>运营变化、搜索获客与内容平台</small></span>${icon('chevron-right')}</a></section></div><section class="quick-map">${heading('从这里继续','项目、内容与经验，连接到同一条行动路径。')}<div class="quick-links">${[['content','开始做内容','选题、三个平台与作品','clapperboard'],['board','展开一个想法','在便签上延伸和整理','lightbulb'],['review','留下今天的积累','记录进展、卡点与下一步','notebook-pen']].map(([r,t,s,i])=>`<a href="#${r}">${icon(i)}<div><strong>${t}</strong><span>${s}</span></div>${icon('arrow-up-right')}</a>`).join('')}</div></section>`;}
  function modules(items){return `<div class="module-grid">${items.map((x,i)=>`<button class="module" data-action="module" data-title="${esc(x[0])}" data-body="${esc(x[1])}"><span class="module-icon">${icon(x[2]||'file-text')}</span><strong>${x[0]}</strong><p>${x[1]}</p><span class="module-open">查看用途与内容 ${icon('arrow-up-right')}</span></button>`).join('')}</div>`;}
  function projects(){return `<section class="goal-banner"><span class="goal-symbol">${icon('target')}</span><div><span>当前主线 · 已确认</span><h2>用 AI 解决工作和生意中的真实问题</h2><p>先服务外贸运营同行，积累实操内容，逐步探索培训与服务；网站业务持续推进。</p></div></section><section class="panel">${heading('正在关注的项目','点击查看当前阶段、完成证据和下一步。')}<div class="project-list">${D.projects.map(p=>projectHTML(p)).join('')}</div></section><section class="section-space">${heading('一个项目，怎样向前走？','通用流程示意；每个具体项目可以调整。')}<div class="workflow">${D.workflows.map((s,i)=>`<div><span>${i+1}</span><strong>${s}</strong></div>`).join('')}</div></section>${modules([['任务与时间','记录T0/T1、下一步、预计时间和实际投入。','list-checks'],['里程碑与证据','记录关键阶段以及可以检查的文件、链接或结果。','target'],['流程与模板','把反复做的操作整理成输入、步骤和验收要求。','file-text']])}`;}
  function content(){const ps=['共用内容库','小红书','抖音','视频号'];return `<div class="tab-bar" aria-label="内容平台">${ps.map(p=>`<button data-action="platform" data-platform="${p}" aria-pressed="${p===platform}" class="${p===platform?'active':''}">${p}</button>`).join('')}</div>${platform==='共用内容库'?`<section class="panel content-feature"><div>${badge('选题候选 · 尚未选定','blue')}<h2>AI 写的外贸内容，为什么和自己的产品对不上？</h2><p>从已有社媒工作台的资料与验收问题切入，讲清品牌资料、产品事实和人工检查。</p><div class="feature-actions"><button class="primary-button" data-action="module" data-title="选题候选" data-body="先核对一个案例的原始资料、可公开范围和前后对照，再决定是否制作。本条只是选题候选，没有发布或效果记录。">查看案例思路 ${icon('arrow-right')}</button>${badge('可公开范围待确认','amber')}</div></div><div class="content-art" aria-hidden="true"><span>问题</span><div></div><span>操作</span><div></div><span>验收</span></div></section><div class="section-space">${heading('共用一份资料，做好不同版本','同一个案例只记录一次，各平台版本分别关联。')}${modules([['选题与案例库','记录问题、受众、案例来源与想传达的核心结论。','lightbulb'],['脚本与素材库','归集提纲、截图、视频素材与可公开范围。','file-text'],['作品与需求反馈','关联最终成品、观众问题和待验证的培训服务需求。','message-square']])}</div>`:`<section class="platform-intro"><span class="platform-symbol ${platform==='小红书'?'red':platform==='视频号'?'amber':'navy'}">${platform.slice(0,1)}</span><div><h2>${platform}内容工作区</h2><p>共用案例与素材，单独记录这个平台的内容版本、发布链接和反馈。</p></div>${badge('账号与数据未接入')}</section>${modules([['账号与定位','记录账号主页、目标受众、介绍和内容方向。当前没有连接真实账号。','target'],['内容版本','记录适合这个平台的标题、封面、正文或视频版本。','clapperboard'],['排期与发布','记录计划日期、检查结果和实际发布链接。不会自动发布。','calendar-days'],['数据与反馈','记录有来源的表现数据、评论问题和下一条内容的调整。当前暂无真实数据。','chart-no-axes-combined']])}<div class="empty-inline">${icon('file-text')}<div><strong>还没有${platform}的发布记录</strong><p>先把一个案例做好，发布后再留下链接与真实反馈。</p></div></div>`}`;}
  function business(){return `<section class="panel business-overview"><div><div class="page-kicker">${icon('globe')}当前网站项目</div><h2>Packrivo 独立站</h2><p>包装采购协调业务：把产品信息、内容获客和客户需求连接起来。</p></div><div>${badge('线上状态待原项目复核','amber')}<button class="text-button" data-action="project" data-id="packrivo">查看项目摘要 ${icon('arrow-up-right')}</button></div></section><div class="section-space">${heading('从网站到业务跟进','以下为功能框架，尚未连接真实业务数据。')}${modules([['站点概况','关注网站当前阶段、问题清单、验收记录与下一步。','globe'],['产品与内容','关联产品资料、产品页面、博客与素材，核对事实和质量。','file-text'],['SEO/GEO与获客','整理搜索表现、内容机会与访问到询盘的关键环节。','radar'],['客户与询盘','记录需求摘要、当前阶段、上次进展与下次跟进。','message-square'],['报价、样品与交付','关联需求确认、报价版本、样品状态和交付证据。','list-checks'],['供应商与供应链','记录适合的产品、核实情况、沟通进度和待确认事项。','globe']])}</div>`;}
  function knowledge(){return `<section class="knowledge-banner">${icon('book-open')}<div><h2>经验有出处，方法能复用。</h2><p>Obsidian 是长期知识主源。这里帮助你找到入口，连接案例、工具和正在做的事。</p></div></section>${modules([['Obsidian知识入口','按主题找到主知识页，保留来源和更新时间；不在工作台复制整个知识库。','book-open'],['Skill与工具','记录能解决什么问题、使用入口、是否试过、适用范围和限制。','compass'],['实战案例','整理问题、操作、结果、失败和完成证据，帮助复用与讲解。','file-text'],['提示词与模板','保留已经实践过的输入范例、检查清单和可重复使用的流程。','notebook-pen'],['学习与能力','记录想解决的问题、当前练习和能证明进步的作品。','target'],['我的工具体验','查看已加入的试用任务；试用后在备注中记录实际效果。','radar']])}<section class="section-space">${heading('已加入的工具尝试','先完成一个小任务，再决定是否长期使用。')}${trialList()}</section>`;}
  function trialList(){return state.trials.length?`<div class="trial-list">${state.trials.map(id=>{const t=D.tools.find(x=>x.id===id);return t?`<button class="trial-row" data-action="tool" data-id="${id}"><span class="tool-mark ${t.tone}">${t.monogram}</span><div><strong>${t.name}</strong><span>${t.trial}</span></div>${badge(state.done['trial-'+id]?'已标记完成':'待尝试',state.done['trial-'+id]?'teal':'blue')}</button>`:'';}).join('')}</div>`:`<div class="empty-inline">${icon('compass')}<div><strong>还没有加入工具试用</strong><p>在资讯与机会里，挑一个与你当前工作有关的工具。</p></div>${link('radar','去看看')}</div>`;}
  function radar(){const filters=['全部','AI 工具','外贸运营','独立站','我的试用'];return `<div class="radar-intro">${icon('radar')}<p><strong>从“听说过”，到“亲手试过”。</strong><span>了解用途与优势，用一个小任务判断它是否适合你。</span></p>${badge('资料核查：2026-10-29')}</div><div class="tab-bar" aria-label="资讯分类">${filters.map(p=>`<button data-action="radar-filter" data-filter="${p}" aria-pressed="${p===radarFilter}" class="${p===radarFilter?'active':''}">${p}${p==='我的试用'?` <span>${state.trials.length}</span>`:''}</button>`).join('')}</div>${radarFilter==='我的试用'?trialList():`<div class="tools-grid">${D.tools.filter(t=>radarFilter==='全部'||t.type===radarFilter).map(t=>toolHTML(t,true)).join('')}</div>`}<p class="quiet-note">${icon('info')}工具介绍引用官方资料，尚未亲手实测；外贸和独立站条目是栏目示例。这里尚未接入实时采集。</p>`;}
  function board(){const ideas=[...D.ideas,...state.ideas];return `<div class="board-toolbar"><p>先把想法留下，再慢慢连接成行动。</p><button class="primary-button" data-action="new-idea">${icon('plus')}新增想法</button></div><div class="board-surface"><div class="board-lanes">${['灵感收集','延伸思考','准备行动'].map((lane,i)=>`<section class="board-lane"><h2><span class="lane-dot lane-${i}"></span>${lane}<small>${ideas.filter(x=>x.lane===lane).length}</small></h2>${ideas.filter(x=>x.lane===lane).map((x,j)=>`<button class="idea-note note-${i}" data-action="module" data-title="${esc(x.title)}" data-body="${esc(x.body)}"><strong>${esc(x.title)}</strong><p>${esc(x.body)}</p><span>${j===0?'框架示例':'我的想法'} ${icon('arrow-up-right')}</span></button>`).join('')}</section>`).join('')}</div></div><p class="quiet-note">${icon('info')}第一版支持新增与查看便签；自由拖拽和连线尚未制作。</p>`;}
  const reviewConfig={daily:{name:'每日记录',intro:'用几句话，为明天留一个清楚的起点。',fields:['今天推进了什么？','遇到了什么问题？','下一步做什么？']},weekly:{name:'每周复盘',intro:'从忙了什么，回到哪些事值得继续。',fields:['本周完成了什么？证据在哪里？','哪些值得继续，哪些应该停止？','下周最重要的一步是什么？']},monthly:{name:'每月复盘',intro:'回看方向、投入和真正留下来的积累。',fields:['目标与业务有了什么进展？','积累了哪些作品、知识与能力？','下个月准备调整什么？']}};
  function review(){const c=reviewConfig[reviewPeriod],saved=state.reviews[reviewPeriod]||[];return `<div class="tab-bar" aria-label="复盘周期">${Object.entries(reviewConfig).map(([k,v])=>`<button data-action="review-period" data-period="${k}" aria-pressed="${reviewPeriod===k}" class="${reviewPeriod===k?'active':''}">${v.name}</button>`).join('')}</div><div class="review-layout"><section class="panel"><div class="review-heading">${icon('notebook-pen')}<div><h2>${c.name}</h2><p>${c.intro}</p></div></div><form id="review-form">${c.fields.map((f,i)=>`<label class="review-field">${f}<textarea name="review-${i}" rows="3" maxlength="5000" placeholder="写下真实进展，简单一点就好。">${esc(saved[i]||'')}</textarea></label>`).join('')}<div class="form-footer"><span>当前周期草稿 · 输入自动保存</span><button class="primary-button" type="submit">保存${c.name}</button></div></form></section><aside class="review-aside"><h2>值得记录的积累</h2><p>不只是做了多少事，也看看留下了什么。</p><ul><li>一个可以展示的作品</li><li>一条经过验证的方法</li><li>一次真实的客户反馈</li><li>一个更清楚的下一步</li></ul>${link('projects','回看项目证据')}</aside></div>`;}
  function render(){const s=D.sections.find(x=>x.id===route);$('#breadcrumb').textContent=s.name;document.title='我的工作台 · '+s.short;$('#nav').innerHTML=D.sections.map((x,i)=>`${i===5?'<div class="nav-divider"><span>积累与探索</span></div>':''}<a class="nav-item ${route===x.id?'active':''}" href="#${x.id}" ${route===x.id?'aria-current="page"':''}>${icon(x.icon)}<span>${x.name}</span>${route===x.id?'<span class="nav-active-dot"></span>':''}</a>`).join('');$('#main').innerHTML=pageHeader()+({home,projects,content,business,knowledge,radar,board,review}[route])()+noteHTML();$('#storage-warning').hidden=storageOK;}
  function navigate(){const id=location.hash.slice(1)||'home';route=D.sections.some(x=>x.id===id)?id:'home';closeMenu();render();window.scrollTo(0,0);}
  function closeMenu(){$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu').setAttribute('aria-expanded','false');}
  function modal(title,html,eyebrow='查看详情'){$('#dialog-title')?.removeAttribute('id');$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-content').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${html}`;$('#dialog').showModal();}
  function detailTool(id){const t=D.tools.find(x=>x.id===id);if(!t)return;modal(t.name,`<p class="dialog-lead">${t.title}</p>${badge(t.type,'blue')}${badge(t.source?'官方介绍 · 未实测':'栏目示例')}<div class="detail-block"><h3>它能做什么</h3><p>${esc(t.capability)}</p><h3>对你有什么帮助</h3><p>${esc(t.benefit)}</p><h3>别人拿来做什么</h3><p>${esc(t.cases)}</p></div><section class="trial-box"><div>${icon('compass')}<strong>给你的 ${t.minutes} 分钟尝试</strong></div><p>${esc(t.trial)}</p><small>看结果：${esc(t.criteria)}</small></section><div class="detail-block"><h3>使用前了解</h3><p>${esc(t.limits)}</p>${t.source?`<a class="source-link" href="${t.source}" target="_blank" rel="noopener noreferrer">${t.sourceName} ${icon('external-link')}</a>`:''}<small class="source-date">资料核查：${t.date}</small></div><div class="dialog-actions"><button class="outline-button" data-action="close">先看看</button><button class="primary-button" data-action="${state.trials.includes(id)?'remove-trial':'add-trial'}" data-id="${t.id}">${icon(state.trials.includes(id)?'check':'plus')}${state.trials.includes(id)?'移出今日尝试':'加入今日尝试'}</button></div>`,'工具与尝试');}
  function searchResults(q){q=q.trim().toLowerCase();const results=[...D.sections.map(s=>({title:s.name,desc:s.desc,action:'go',id:s.id,icon:s.icon})),...D.tools.map(t=>({title:t.name,desc:t.title,action:'tool',id:t.id,icon:'radar'})),...D.projects.map(p=>({title:p.title,desc:p.next,action:'project',id:p.id,icon:p.icon}))].filter(x=>!q||(x.title+x.desc).toLowerCase().includes(q));$('#search-results').innerHTML=results.length?results.map(r=>`<button class="search-result" data-action="${r.action}" data-id="${r.id}">${icon(r.icon)}<span><strong>${r.title}</strong><small>${r.desc}</small></span>${icon('chevron-right')}</button>`).join(''):`<div class="search-empty">没有找到相关内容。试试“工具”“自媒体”或“项目”。</div>`;}
  document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
    if(a==='close'){$('#dialog').close();return;}
    if(a==='section-help'){const p=$('#section-explainer');p.hidden=!p.hidden;el.setAttribute('aria-expanded',String(!p.hidden));return;}
    if(a==='guide'){modal('把这个工作台，当作你的日常入口',`<div class="detail-block"><h3>从首页开始</h3><p>今日任务可以勾选，项目可以打开查看阶段，工具推荐可以加入尝试。侧栏可进入全部八个板块。</p><h3>看不懂时，点“板块说明”</h3><p>每个板块都有用途说明；下方的备注区可以记录你想增加或调整的内容。</p><h3>哪些会保存？</h3><p>任务状态、自己添加的任务、工具试用、备注、便签和复盘草稿，保存在当前浏览器。不同浏览器、文件打开与网址打开的数据可能各自独立；清理浏览器数据会丢失记录。当前请先使用非敏感体验内容。</p><h3>这次能体验什么？</h3><p>八板块浏览与本地小交互。没有连接真实账号、客户数据或实时资讯，也不会自动发帖。示例和待核实状态均有标注。</p></div>`,'使用说明');return;}
    if(a==='task'){const t=allTasks().find(x=>x.id===id);modal(t.title,`<p class="dialog-lead">${t.tag} · 建议 ${t.minutes} 分钟</p><div class="detail-block"><h3>怎么做</h3><p>${esc(t.body)}</p><h3>怎样算完成</h3><p>${esc(t.evidence||'完成你为这个任务设定的动作，并在备注中留下结果。')}</p></div><p class="quiet-note">这是本地计划与勾选记录，不会自动执行或对外发布。</p>`,'今日任务');return;}
    if(a==='project'){const p=D.projects.find(x=>x.id===id);if(!p)return;modal(p.title,`${badge(p.stage,'blue')}<p class="dialog-lead">${p.desc}</p><div class="detail-block"><h3>下一步</h3><p>${p.next}</p><h3>目前知道什么</h3><p>${p.evidence}</p></div><div class="dialog-actions"><button class="primary-button" data-action="go" data-id="${p.route}">进入相关板块 ${icon('arrow-right')}</button></div>`,'项目进度与证据');return;}
    if(a==='tool'){if($('#dialog').open)$('#dialog').close();detailTool(id);return;}
    if(a==='remove-trial'){M.removeTrial(state,id);save();render();$('#dialog').close();toast('已移出今日尝试，可以重新加入');return;}
    if(a==='add-trial'){if(M.addTrial(state,id)){save();render();toast('已加入今日任务，可在首页勾选完成');}$('#dialog').close();return;}
    if(a==='module'){modal(el.dataset.title,`<p class="dialog-lead">${esc(el.dataset.body)}</p><div class="detail-block"><h3>这里怎么用</h3><p>先查看这个板块需要记录的内容，再在页面下方写下你希望补充的功能。当前是框架预览，没有接入外部业务系统。</p></div>`,'板块用途');return;}
    if(a==='platform'){platform=el.dataset.platform;render();return;}
    if(a==='radar-filter'){radarFilter=el.dataset.filter;render();return;}
    if(a==='review-period'){reviewPeriod=el.dataset.period;render();return;}
    if(a==='go'){if($('#dialog').open)$('#dialog').close();if(location.hash==='#'+id){route=id;render();}else location.hash=id;return;}
    if(a==='new-task'){modal('给今天加一件事',`<form id="task-form"><label class="form-field">要做什么<input name="title" required maxlength="120" placeholder="写一个具体的小行动"></label><label class="form-field">预计时间<select name="minutes"><option value="15">15 分钟</option><option value="20">20 分钟</option><option value="25">25 分钟</option><option value="30">30 分钟</option><option value="60">60 分钟</option></select></label><p class="quiet-note">增加任务后，记得看看总时长是否适合今天。</p><div class="dialog-actions"><button class="outline-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">添加到今天</button></div></form>`,'我的安排');return;}
    if(a==='new-idea'){modal('留住一个想法',`<form id="idea-form"><label class="form-field">想法标题<input name="title" required maxlength="80" placeholder="你正在想什么？"></label><label class="form-field">再展开一点<textarea name="body" required rows="4" maxlength="1500" placeholder="写一点问题、关联或下一步想探索的内容。"></textarea></label><label class="form-field">放在哪里<select name="lane"><option>灵感收集</option><option>延伸思考</option><option>准备行动</option></select></label><div class="dialog-actions"><button class="outline-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">保存想法</button></div></form>`,'思考画板');return;}
    if(a==='search'){modal('找一件事',`<label class="sr-only" for="search-input">搜索内容</label><input id="search-input" class="search-input" placeholder="搜索板块、项目或工具…" type="search" autocomplete="off"><div id="search-results"></div>`,'快速查找');searchResults('');$('#search-input').focus();}
  });
  document.addEventListener('change',ev=>{if(ev.target.matches('[data-task]')){const id=ev.target.dataset.task;M.toggleTask(state,id);save();render();$('#done-'+id)?.focus();}});
  document.addEventListener('input',ev=>{if(ev.target.id==='search-input')searchResults(ev.target.value);if(ev.target.id==='section-note'){state.notes[route]=ev.target.value;save();}if(ev.target.closest('#review-form')){const f=new FormData($('#review-form'));state.reviews[reviewPeriod]=[0,1,2].map(i=>String(f.get('review-'+i)||''));save();}});
  document.addEventListener('submit',ev=>{if(!['note-form','review-form','task-form','idea-form'].includes(ev.target.id))return;ev.preventDefault();const f=new FormData(ev.target);
    if(ev.target.id==='note-form'){state.notes[route]=String(f.get('note')||'');save();toast('板块备注已保存');}
    if(ev.target.id==='review-form'){state.reviews[reviewPeriod]=[0,1,2].map(i=>String(f.get('review-'+i)||''));save();toast(reviewConfig[reviewPeriod].name+'已保存');}
    if(ev.target.id==='task-form'){if(!M.addTask(state,String(f.get('title')),f.get('minutes'))){toast('请写一个具体任务');return;}save();$('#dialog').close();render();toast('已添加到今日任务');}
    if(ev.target.id==='idea-form'){const title=String(f.get('title')||'').trim(),body=String(f.get('body')||'').trim();if(!title||!body)return;state.ideas.push({title,body,lane:String(f.get('lane'))});save();$('#dialog').close();render();toast('想法已保存');}
  });
  $('#menu').addEventListener('click',()=>{const on=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',on);$('#scrim').hidden=!on;$('#menu').setAttribute('aria-expanded',String(on));});
  $('#scrim').addEventListener('click',closeMenu);
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){if($('#dialog').open){ev.preventDefault();$('#dialog').close();}closeMenu();}if(ev.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName)&&!$('#dialog').open){ev.preventDefault();$('.search-trigger').click();}});
  $('.skip-link').addEventListener('click',ev=>{ev.preventDefault();$('#main').focus();});
  window.addEventListener('hashchange',navigate);navigate();
})();
